:root {
  --color-bg: #faf7f2;
  --color-bg-alt: #eef0e6;
  --color-text: #2a2621;
  --color-text-muted: #5a544c;
  --color-primary: #2f4f2f;
  --color-primary-dark: #1f351f;
  --color-accent: #b5895e;
  --color-dark-bg: #2e3326;
  --color-accent-on-dark: #e8dcc8;
  --color-white: #ffffff;
  --color-border: #d9d2c3;
  --font-body: 'Palatino Linotype', 'Book Antiqua', Georgia, serif;
  --font-heading: 'Palatino Linotype', 'Book Antiqua', Georgia, serif;
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 3rem;
  --space-xl: 5rem;
  --radius: 0.5rem;
  --max-width: 75rem;
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body);
  background-color: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  font-size: 1rem;
}

h1, h2, h3, h4 {
  font-family: var(--font-heading);
  color: var(--color-primary);
  line-height: 1.25;
  margin-top: 0;
}

h1 { font-size: clamp(2rem, 5vw, 3rem); }
h2 { font-size: clamp(1.5rem, 3.5vw, 2.2rem); }
h3 { font-size: 1.25rem; }

p { margin-top: 0; color: var(--color-text); }

img { max-width: 100%; height: auto; display: block; }

a {
  color: var(--color-primary);
  text-decoration: underline;
}

a:hover { color: var(--color-primary-dark); }

a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible, select:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.25rem;
  width: 100%;
}

/* Header */
header {
  background-color: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
  padding: var(--space-sm) 0;
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
}

.logo {
  font-family: 'Palatino Linotype', 'Book Antiqua', Georgia, serif;
  font-variant: small-caps;
  font-weight: 400;
  letter-spacing: 0.25em;
  font-size: clamp(1.1rem, 3vw, 1.5rem);
  color: var(--color-primary);
  text-decoration: none;
  border-bottom: 1px solid var(--color-accent);
  width: fit-content;
  padding-bottom: 0.15em;
}

.logo:hover { color: var(--color-primary-dark); }

nav[aria-label="Main"] ul.nav-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin: 0;
  padding: 0;
}

nav[aria-label="Main"] a {
  text-decoration: none;
  color: var(--color-text);
  font-weight: 600;
  padding: 0.3rem 0.2rem;
}

nav[aria-label="Main"] a:hover {
  color: var(--color-primary);
  text-decoration: underline;
}

/* Footer */
footer {
  background-color: var(--color-dark-bg);
  color: var(--color-accent-on-dark);
  padding: var(--space-lg) 0;
  margin-top: var(--space-xl);
}

footer a {
  color: var(--color-accent-on-dark);
  text-decoration: underline;
}

footer a:hover { color: var(--color-white); }

.footer-inner { text-align: center; }

.footer-name {
  font-size: 1.2rem;
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

address { font-style: normal; margin-bottom: var(--space-sm); }

.copyright { font-size: 0.875rem; opacity: 0.9; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.75rem 1.75rem;
  border-radius: var(--radius);
  border: 2px solid var(--color-primary);
  background-color: var(--color-primary);
  color: var(--color-white);
  font-size: 1rem;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease;
}

.btn:hover {
  background-color: var(--color-primary-dark);
  border-color: var(--color-primary-dark);
  color: var(--color-white);
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary);
}

.btn-secondary:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

/* Cards */
.card {
  background-color: var(--color-white);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--space-md);
}

.card h3 { margin-bottom: var(--space-xs); }

/* Grid helper */
.grid {
  display: grid;
  gap: var(--space-md);
  grid-template-columns: 1fr;
}

/* Sections */
section {
  padding: var(--space-xl) 0;
}

.section-alt {
  background-color: var(--color-bg-alt);
}

.section-dark {
  background-color: var(--color-dark-bg);
  color: var(--color-accent-on-dark);
}

.section-dark h2, .section-dark h3 { color: var(--color-accent-on-dark); }

/* Forms */
form {
  display: grid;
  gap: var(--space-sm);
  max-width: 32rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

label {
  font-weight: 700;
  color: var(--color-text);
}

.section-dark label { color: var(--color-accent-on-dark); }

input, textarea, select {
  min-height: 44px;
  padding: 0.6rem 0.8rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  font-family: inherit;
  font-size: 1rem;
  background-color: var(--color-white);
  color: var(--color-text);
}

textarea { min-height: 7rem; resize: vertical; }

/* Table */
table {
  width: 100%;
  border-collapse: collapse;
  background-color: var(--color-white);
}

table caption { text-align: left; font-weight: 700; margin-bottom: var(--space-sm); }

th, td {
  text-align: left;
  padding: 0.75rem;
  border-bottom: 1px solid var(--color-border);
}

th { background-color: var(--color-bg-alt); color: var(--color-primary); }

.table-wrapper { overflow-x: auto; }

/* Mobile breakpoint */
@media (max-width: 600px) {
  .container { padding: 0 1rem; }
  .header-inner { flex-direction: column; align-items: flex-start; }
  nav[aria-label="Main"] ul.nav-list { flex-direction: column; gap: 0.5rem; width: 100%; }
  section { padding: var(--space-lg) 0; }
  h1 { font-size: 1.75rem; }
  h2 { font-size: 1.4rem; }
  .grid { grid-template-columns: 1fr; }
}

/* Desktop breakpoint */
@media (min-width: 601px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .header-inner { flex-wrap: nowrap; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  * { animation: none !important; transition: none !important; }
}

