.index-hero { padding-top: var(--space-xl); padding-bottom: var(--space-xl); }
.index-hero-inner { display: grid; grid-template-columns: 1fr; gap: var(--space-lg); align-items: center; }
.index-hero-text { order: 2; }
.index-hero-img { order: 1; border-radius: var(--radius); width: 100%; }
.index-hero-lead { font-size: 1.1rem; color: var(--color-text-muted); margin-bottom: var(--space-md); }
.index-hero-cta { font-size: 1.05rem; }

.index-section-intro { max-width: 42rem; color: var(--color-text-muted); margin-bottom: var(--space-lg); }
.index-signup-intro { color: var(--color-accent-on-dark); opacity: 0.9; }

.index-price-card { text-align: center; display: flex; flex-direction: column; gap: var(--space-xs); }
.index-price { font-size: 2rem; font-weight: 700; color: var(--color-primary); margin: 0; }
.index-price span { font-size: 1rem; font-weight: 400; color: var(--color-text-muted); }
.index-price-featured { border-color: var(--color-primary); border-width: 2px; }

.index-quote { border-left: 4px solid var(--color-accent); margin: 0; }
.index-quote p { font-style: italic; }
.index-quote footer { margin-top: var(--space-sm); font-weight: 700; color: var(--color-primary); }

.index-signup-inner form { background-color: var(--color-dark-bg); }
.index-signup-btn { width: 100%; font-size: 1.05rem; }

@media (max-width: 600px) {
  .index-hero-img { order: 1; }
  .index-price { font-size: 1.6rem; }
}

@media (min-width: 601px) {
  .index-hero-inner { grid-template-columns: 1.1fr 1fr; }
  .index-hero-text { order: 1; }
  .index-hero-img { order: 2; }
  .index-signup-btn { width: auto; }
}

